class Solution:
    def minOperations(self, s: str) -> int:
        # Count operations to make all '0' or all '1'
        # An operation can flip a contiguous segment of characters
        # The number of flips to make all '0' is the number of contiguous blocks of '1's
        # The number of flips to make all '1' is the number of contiguous blocks of '0's
        blocks_0 = 0
        blocks_1 = 0
        n = len(s)

        i = 0
        while i < n:
            ch = s[i]
            if ch == '0':
                blocks_0 += 1
            else:
                blocks_1 += 1
            while i < n and s[i] == ch:
                i += 1

        return min(blocks_0, blocks_1)
