#include <string>
#include <algorithm>

class Solution {
public:
    int minOperations(std::string s) {
        int blocks_0 = 0, blocks_1 = 0;
        int n = s.size();
        int i = 0;
        while (i < n) {
            char ch = s[i];
            if (ch == '0') blocks_0++;
            else blocks_1++;
            while (i < n && s[i] == ch) i++;
        }
        return std::min(blocks_0, blocks_1);
    }
};

class Solution {
    public int minOperations(String s) {
        int blocks0 = 0, blocks1 = 0;
        int n = s.length();
        int i = 0;
        while (i < n) {
            char ch = s.charAt(i);
            if (ch == '0') blocks0++;
            else blocks1++;
            while (i < n && s.charAt(i) == ch) i++;
        }
        return Math.min(blocks0, blocks1);
    }
}

var minOperations = function(s) {
